[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts may not be present in a single-file shelf aisle, a layout-invariant rule based on local clearance and shelf adjacency rather than observed coordinates.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_shelf_aisle_with_cart",
    "text": "Before entering a single-file shelf aisle the shopper must already be separated from the cart, which generalizes to any rearranged store because it refers to the transition into a locally narrow shelf passage.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    }
  },
  {
    "id": "no_cart_item_interaction_between_opposing_shelves",
    "text": "A shopper must not interact with shelf goods while holding a cart in a single-file aisle flanked by shelves, capturing the rotated aisle cases without relying on fixed aisle orientation.",
    "abstraction": {
      "state_properties": {
        "opposingShelvesSingleFile": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "opposingShelvesSingleFile"
        ]
      }
    }
  },
  {
    "id": "cartless_shelf_interaction_only_in_cramped_aisles",
    "text": "Interacting with shelves while not holding the cart is permitted only in single-file shelf aisles, distinguishing deliberate cart-parking from arbitrary cart abandonment in ordinary spacious aisles.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "hasCart"
          },
          "adjShelf",
          {
            "not": "singleFileShelfAisle"
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_wide_clearance_area",
    "text": "A cart may be parked only in an area with ample horizontal and vertical clearance, so the rule follows the functional role of a staging space rather than a particular entry coordinate.",
    "abstraction": {
      "state_properties": {
        "wideClearanceArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideClearanceArea"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_park_cart_at_shelf_front",
    "text": "A shopper must not park a cart directly next to a shelf, which generalizes as a prohibition on blocking shelf access rather than on parking at any specific observed cell.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          "adjShelf"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart, the shopper is obliged to retrieve a cart before leaving, a behavioral norm over cart-transfer events that remains meaningful under changed layouts.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "must_have_cart_during_shopping_trip",
    "text": "From the start of the shopping trip the shopper is obliged eventually to have a cart, a task-independent norm about using store carts rather than a coordinate-dependent route regularity.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  }
]

